// Copies the compiled Hollow ABI and the Archive map into the web app.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const root = new URL('../../', import.meta.url);
const art = JSON.parse(readFileSync(new URL('contracts/out/Hollow.sol/Hollow.json', root)));
mkdirSync(new URL('src/chain/', new URL('../', import.meta.url)), { recursive: true });
writeFileSync(new URL('../src/chain/abi.ts', import.meta.url),
  '// generated by scripts/sync-contract.mjs — do not edit\nexport const hollowAbi = ' + JSON.stringify(art.abi, null, 2) + ' as const;\n');
const map = JSON.parse(readFileSync(new URL('tools/map/hollow-map.json', root)));
writeFileSync(new URL('../src/map.json', import.meta.url), JSON.stringify(map));
console.log('abi entries', art.abi.length, '| map seed', map.seed);
